package com.example.crm.task;
import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/tasks") public class TaskController { final TaskRepository repo; TaskController(TaskRepository r){repo=r;} record Req(@NotBlank String title,LocalDate dueDate,UUID customerId,UUID dealId){} @GetMapping public List<TaskItem> all(){return repo.findAll();} @PostMapping public TaskItem create(@Valid @RequestBody Req r){return repo.save(new TaskItem(r.title(),r.dueDate(),r.customerId(),r.dealId()));} @PatchMapping("/{id}/complete") public TaskItem complete(@PathVariable UUID id){var t=repo.findById(id).orElseThrow();t.setCompleted(true);return repo.save(t);} }
